public static async ensureSfnt(buf: Uint8Array): Promise<Uint8Array> {
    if (buf.length >= 4) {
        if (buf[0] === 0x77 && buf[1] === 0x4f && buf[2] === 0x46 && buf[3] === 0x32) {
            const decompress = (await import('woff2-encoder/decompress')).default;
            return await decompress(buf);
        }
        if (buf[0] === 0x77 && buf[1] === 0x4f && buf[2] === 0x46 && buf[3] === 0x46) {
            const opentype = (await import('opentype.js')).default;
            const arrayBuf = buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength) as ArrayBuffer;
            const fontObj = opentype.parse(arrayBuf);
            return new Uint8Array(fontObj.toArrayBuffer());
        }
    }
    return buf;
}

private static sanitizeInvertedGlyphs(atlas: MSDFAtlas): void {
    const data = atlas.texture.data;
    const texWidth = atlas.textureSize[0];
    const median = (r: number, g: number, b: number) => Math.max(Math.min(r, g), Math.min(Math.max(r, g), b));

    for (const g of atlas.glyphs) {
        const [gx, gy] = g.atlasPosition;
        const [gw, gh] = g.atlasSize;
        if (gw < 3 || gh < 3) continue;

        const corners = [
            [gx, gy], [gx + gw - 1, gy],
            [gx, gy + gh - 1], [gx + gw - 1, gy + gh - 1]
        ];

        let cornerInsideCount = 0;
        for (const [cx, cy] of corners) {
            const idx = (cy * texWidth + cx) * 4;
            if (median(data[idx], data[idx + 1], data[idx + 2]) > 127) cornerInsideCount++;
        }

        // If >= 3 corners are positive, the glyph distance field is inverted
        if (cornerInsideCount >= 3) {
            for (let py = 0; py < gh; py++) {
                for (let px = 0; px < gw; px++) {
                    const idx = ((gy + py) * texWidth + (gx + px)) * 4;
                    data[idx + 0] = 255 - data[idx + 0];
                    data[idx + 1] = 255 - data[idx + 1];
                    data[idx + 2] = 255 - data[idx + 2];
                }
            }
        }
    }
}

