import { FontLoader, SDFText, Scene, Color, CENTER } from "retiam";

export class MyScene extends Scene {
    public async run() {
        // Enable persistent disk caching across reloads (recommended for development)
        FontLoader.defaultPersist = true;

        // Load a Google Font dynamically via in-browser WASM
        const pliant = await FontLoader.msdf("Pliant");

        // Load a local pre-baked font (0ms load time)
        const roboto = await FontLoader.msdf("/fonts/Roboto.json");

        const text = new SDFText("Hello WebGPU!", {
            font: pliant,          // Font instance, or use the built-in alias: font: "roboto"
            fontSize: 1.2,
            anchor: CENTER,
            fill: new Color(0.2, 0.8, 1.0, 1.0)
        });
        this.add(text);
    }
}

